urces","label":"Finance sources — specify","type":"multi","options":["Microfinance bank","BOI","SMEDAN","Cooperative savings","NGO/Donor"],"required":true,"show":["finance","Yes"],"sourceDocument":"Form 4   Cassava Cooperative  Community Survey   (Jigawa LGA-wise).docx","sourceSection":"Marketing & Finance"},{"id":"pastSupport","label":"Has the cooperative received government/NGO support?","type":"multi","options":["Input distribution (seed, fertilizer, stems)","Grants/Loans","Equipment support (graters, dryers, presses, packaging units)","Training/Capacity building","None"],"required":true,"sourceDocument":"Form 4   Cassava Cooperative  Community Survey   (Jigawa LGA-wise).docx","sourceSection":"Support & Capacity Building"},{"id":"support","label":"What support is most needed?","type":"multi","options":["Improved cassava varieties","Processing equipment","Storage/warehousing","Branding & packaging tools","Finance/credit","Market linkage","Export support"],"required":true,"sourceDocument":"Form 4   Cassava Cooperative  Community Survey   (Jigawa LGA-wise).docx","sourceSection":"Support & Capacity Building"},{"id":"training","label":"Training needs","type":"multi","options":["Cooperative management & governance","Record keeping & financial literacy","Cassava agronomy","Post-harvest handling","Processing/value addition","Branding & marketing","Food safety & certification (NAFDAC/SON)"],"required":true,"sourceDocument":"Form 4   Cassava Cooperative  Community Survey   (Jigawa LGA-wise).docx","sourceSection":"Support & Capacity Building"},{"id":"comments","label":"Additional comments","type":"textarea","options":[],"required":false,"sourceDocument":"Form 4   Cassava Cooperative  Community Survey   (Jigawa LGA-wise).docx","sourceSection":"Support & Capacity Building"}]$forms$::jsonb)
on conflict(type) do update set version=excluded.version,fields=excluded.fields;
create or replace function public.fieldwork_validate_answers(p_type text,p_answers jsonb) returns boolean
 language plpgsql stable security definer set search_path=public,pg_temp as $$
declare f jsonb; v jsonb; wanted jsonb; rowname text; opt jsonb; n numeric; rules jsonb; skip boolean; condition jsonb;
begin
 if jsonb_typeof(p_answers)<>'object' then return false; end if;
 select fields into rules from public.fieldwork_form_definitions where type=p_type;
 if rules is null then return false; end if;
 for f in select value from jsonb_array_elements(rules) loop
  skip:=false;
  if f ? 'show' then
   wanted:=p_answers->(f->'show'->>0);
   if jsonb_typeof(wanted)='array' then skip:=not(wanted @> jsonb_build_array(f->'show'->1));
   else skip:=wanted is distinct from f->'show'->1; end if;
  end if;
  if f ? 'showIn' then skip:=skip or not(coalesce(f->'showIn'->1 @> jsonb_build_array(p_answers->(f->'showIn'->>0)),false)); end if;
  if f ? 'showAll' then
   for condition in select value from jsonb_array_elements(f->'showAll') loop
    wanted:=p_answers->(condition->>0);
    if jsonb_typeof(wanted)='array' then skip:=skip or not(coalesce(wanted @> jsonb_build_array(condition->1),false));
    else skip:=skip or wanted is distinct from condition->1; end if;
   end loop;
  end if;
  if skip then continue; end if;
  v:=p_answers->(f->>'id');
  if coalesce((f->>'required')::boolean,false) and (v is null or v='null'::jsonb or v='""'::jsonb or v='[]'::jsonb) then
   if f->>'type' not in ('matrix','fixedMatrix') then return false; end if;
  end if;
  if v is null or v='null'::jsonb or v='""'::jsonb then
   if f->>'type' not in ('matrix','fixedMatrix') then continue; end if;
  end if;
  if f->>'type'='number' then
   begin n:=(v#>>'{}')::numeric; exception when others then return false; end;
   if n::text in ('NaN','Infinity','-Infinity') then return false; end if;
   if f ? 'min' and n<(f->>'min')::numeric then return false; end if;
   if f ? 'max' and n>(f->>'max')::numeric then return false; end if;
   if coalesce((f->>'integer')::boolean,false) and trunc(n)<>n then return false; end if;
  elsif f->>'type'='select' then
   if jsonb_typeof(v)<>'string' or not(f->'options' @> jsonb_build_array(v)) then return false; end if;
  elsif f->>'type'='multi' then
   if jsonb_typeof(v)<>'array' then return false; end if;
   for opt in select value from jsonb_array_elements(v) loop if not(f->'options' @> jsonb_build_array(opt)) then return false; end if; end loop;
   if f ? 'maxSelections' and jsonb_array_length(v)>(f->>'maxSelections')::integer then return false; end if;
   if jsonb_array_length(v)>1 and (v @> '["None"]'::jsonb or v @> '["Not Applicable"]'::jsonb) then return false; end if;
   if jsonb_array_length(v)>1 and f ? 'exclusiveOptions' then for opt in select value from jsonb_array_elements(f->'exclusiveOptions') loop if v @> jsonb_build_array(opt) then return false; end if; end loop; end if;
  elsif f->>'type' in ('matrix','fixedMatrix') then
   wanted:=coalesce(f->'fixedRows',p_answers->(f->>'rows'),'[]'::jsonb);
   for rowname in select jsonb_array_elements_text(wanted) loop
    if rowname='Not Applicable' then continue; end if;
    if not(coalesce(f->'options' @> jsonb_build_array(v->rowname),false)) then return false; end if;
   end loop;
  elsif jsonb_typeof(v)<>'string' then return false;
  elsif length(v#>>'{}')>5000 then return false;
  end if;
 end loop;
 return coalesce(p_answers->>'consent'='Yes',false);
exception when others then return false;
end $$;
revoke all on function public.fieldwork_validate_answers(text,jsonb) from public,anon,authenticated;


-- Extend the existing account/assignment/version-checked save path, preserving its permissions.
do $migration$
declare definition text;
begin
 definition:=pg_get_functiondef('public.fieldwork_dispatch_core(text,text,jsonb)'::regprocedure);
 if position('typ not in (''HH'',''FGD'',''KII'',''ENT'')' in definition)=0 then raise exception 'Unexpected dispatcher definition; review before applying';end if;
 definition:=replace(definition,'typ not in (''HH'',''FGD'',''KII'',''ENT'')','typ not in (''HH'',''FGD'',''KII'',''ENT'',''CF'',''CT'',''CP'',''CC'')');
 execute definition;
end $migration$;
-- Study membership is always derived from the instrument, never trusted from clients.
create function public.fieldwork_study_tag() returns trigger language plpgsql set search_path=public as $$
begin new.payload:=new.payload||jsonb_build_object('studyGroup',case when new.type in ('CF','CT','CP','CC') then 'cassava' else 'livelihood' end);return new;end $$;
create trigger fieldwork_study_tag before insert or update on public.fieldwork_records for each row execute function public.fieldwork_study_tag();
revoke all on function public.fieldwork_study_tag() from public,anon,authenticated;
commit;
